<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Lead extends Model {protected $fillable=['first_name','last_name','company','job_title','email','phone','linkedin_url','website','industry','location','source','status','lead_score','notes','owner_id','campaign_id','last_contacted_at'];protected function casts():array{return ['last_contacted_at'=>'datetime','lead_score'=>'integer'];}public function owner(){return $this->belongsTo(User::class,'owner_id');}public function campaign(){return $this->belongsTo(Campaign::class);}public function getFullNameAttribute(){return trim($this->first_name.' '.$this->last_name);}}